<script setup lang="ts">
import { ref } from 'vue'; import { apiClient } from '@/services/api'
const employeeId=ref('');const startDate=ref('');const endDate=ref('');const status=ref('');const loading=ref(false);const error=ref('');const success=ref('')
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
async function attendance(){loading.value=true;error.value='';try{download(await apiClient.exportAttendanceCSV(employeeId.value||undefined,startDate.value||undefined,endDate.value||undefined),'attendance.csv');success.value='Attendance CSV downloaded.'}catch(e){error.value=apiClient.getErrorMessage(e)}finally{loading.value=false}};async function leave(){loading.value=true;error.value='';try{download(await apiClient.exportLeaveCSV(status.value||undefined),'leave.csv');success.value='Leave CSV downloaded.'}catch(e){error.value=apiClient.getErrorMessage(e)}finally{loading.value=false}}
</script>
<template><main class="mx-auto max-w-3xl space-y-6"><h1 class="text-2xl font-bold">Reports</h1><div v-if="error" class="rounded bg-red-50 p-3 text-red-700">{{ error }}</div><div v-if="success" class="rounded bg-green-50 p-3 text-green-700">{{ success }}</div><section class="space-y-4 rounded-lg bg-white p-6 shadow"><h2 class="text-lg font-semibold">Attendance CSV</h2><div class="grid gap-3 sm:grid-cols-3"><input v-model="employeeId" placeholder="Employee ID" class="rounded border p-2" /><input v-model="startDate" type="date" class="rounded border p-2" /><input v-model="endDate" type="date" class="rounded border p-2" /></div><button class="rounded bg-indigo-600 px-4 py-2 text-white" :disabled="loading" @click="attendance">Export attendance</button></section><section class="space-y-4 rounded-lg bg-white p-6 shadow"><h2 class="text-lg font-semibold">Leave CSV</h2><select v-model="status" class="rounded border p-2"><option value="">All statuses</option><option>PENDING</option><option>APPROVED</option><option>REJECTED</option></select><button class="ml-3 rounded bg-indigo-600 px-4 py-2 text-white" :disabled="loading" @click="leave">Export leave</button></section></main></template>
